private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int limit = bb.limit();
    if (i >= limit) {
        return i;
    }
    int b1 = bb.get(i) & 0xFF;
    int codePoint;
    int seqLen;
    if ((b1 & 0x80) == 0) {
        // 1-byte sequence
        codePoint = b1;
        seqLen = 1;
    } else if ((b1 & 0xE0) == 0xC0) {
        // 2-byte sequence
        if (i + 1 >= limit) {
            return i;
        }
        int b2 = bb.get(i + 1) & 0xFF;
        if ((b2 & 0xC0) != 0x80) {
            return i;
        }
        codePoint = ((b1 & 0x1F) << 6) | (b2 & 0x3F);
        seqLen = 2;
    } else if ((b1 & 0xF0) == 0xE0) {
        // 3-byte sequence
        if (i + 2 >= limit) {
            return i;
        }
        int b2 = bb.get(i + 1) & 0xFF;
        int b3 = bb.get(i + 2) & 0xFF;
        if ((b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80) {
            return i;
        }
        codePoint = ((b1 & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F);
        seqLen = 3;
    } else if ((b1 & 0xF8) == 0xF0) {
        // 4-byte sequence
        if (i + 3 >= limit) {
            return i;
        }
        int b2 = bb.get(i + 1) & 0xFF;
        int b3 = bb.get(i + 2) & 0xFF;
        int b4 = bb.get(i + 3) & 0xFF;
        if ((b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80 || (b4 & 0xC0) != 0x80) {
            return i;
        }
        codePoint = ((b1 & 0x07) << 18) | ((b2 & 0x3F) << 12) | ((b3 & 0x3F) << 6) | (b4 & 0x3F);
        seqLen = 4;
    } else {
        // Invalid first byte
        return i;
    }

    if (codePoint <= 0xFFFF) {
        sb.append((char) codePoint);
    } else {
        // Encode as surrogate pair
        codePoint -= 0x10000;
        char high = (char) ((codePoint >> 10) + 0xD800);
        char low = (char) ((codePoint & 0x3FF) + 0xDC00);
        sb.append(high).append(low);
    }

    return i + seqLen;
}

