public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    try {
        if (!(genericType instanceof ParameterizedType) || targetType == null) {
            return null;
        }
        ParameterizedType pType = (ParameterizedType) genericType;
        Type raw = pType.getRawType();
        if (!(raw instanceof Class)) {
            return null;
        }
        Class<?> rawClass = (Class<?>) raw;
        if (!rawClass.isAssignableFrom(targetType)) {
            return null;
        }
        java.util.Map<java.lang.reflect.TypeVariable<?>, Type> typeVarMap = new java.util.HashMap<>();
        buildTypeVariableMap(targetType, typeVarMap);
        Type[] args = pType.getActualTypeArguments();
        Class<?>[] result = new Class<?>[args.length];
        for (int i = 0; i < args.length; i++) {
            Type arg = args[i];
            Type resolved = resolveType(arg, typeVarMap);
            if (resolved instanceof Class) {
                result[i] = (Class<?>) resolved;
            } else if (resolved instanceof ParameterizedType) {
                Type rt = ((ParameterizedType) resolved).getRawType();
                if (rt instanceof Class) {
                    result[i] = (Class<?>) rt;
                } else {
                    return null;
                }
            } else if (resolved instanceof java.lang.reflect.GenericArrayType) {
                Type comp = ((java.lang.reflect.GenericArrayType) resolved).getGenericComponentType();
                Class<?> compClass = resolveComponentClass(comp, typeVarMap);
                if (compClass == null) {
                    return null;
                }
                result[i] = java.lang.reflect.Array.newInstance(compClass, 0).getClass();
            } else if (resolved instanceof java.lang.reflect.WildcardType) {
                Type[] upper = ((java.lang.reflect.WildcardType) resolved).getUpperBounds();
                if (upper.length > 0) {
                    Type ub = upper[0];
                    if (ub instanceof Class) {
                        result[i] = (Class<?>) ub;
                    } else {
                        return null;
                    }
                } else {
                    return null;
                }
            } else {
                return null;
            }
        }
        return result;
    } catch (Exception e) {
        return null;
    }
}

