public Mappings diffStructure(String tableName, Mappings mappings) {
    if (tableName == null || mappings == null) {
        return null;
    }
    try {
        // Retrieve the current mapping for the specified table
        Mappings current = getMapping(tableName);
        if (current == null) {
            return null;
        }

        // Assume Mappings exposes its field definitions via getSource() (a Map<String,Object>)
        Map<String, Object> currentFields = current.getSource();
        Map<String, Object> inputFields   = mappings.getSource();

        if (currentFields == null || inputFields == null) {
            return null;
        }

        // Build a map of fields that exist in the current mapping but not in the input mapping
        Map<String, Object> diffFields = new LinkedHashMap<>();
        for (Map.Entry<String, Object> entry : currentFields.entrySet()) {
            String field = entry.getKey();
            // Skip the _source configuration to avoid update conflicts
            if ("_source".equals(field)) {
                continue;
            }
            if (!inputFields.containsKey(field)) {
                diffFields.put(field, entry.getValue());
            }
        }

        // Construct the resulting Mappings object containing only the diff fields
        Mappings result = new Mappings();
        result.setSource(diffFields);
        return result;
    } catch (Exception e) {
        // In case of any unexpected error, return null (or consider logging the exception)
        return null;
    }
}

