static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep <= 0){
        throw new IllegalArgumentException("dayStep must be positive");
    }
    long year = timeBucket / 10000;
    int month = (int)(timeBucket / 100 % 100);
    int day = (int)(timeBucket % 100);
    try{
        java.time.LocalDate date = java.time.LocalDate.of((int)year, month, day);
        java.time.LocalDate firstDay = java.time.LocalDate.of((int)year, month, 1);
        long daysBetween = java.time.temporal.ChronoUnit.DAYS.between(firstDay, date);
        long remainder = daysBetween % dayStep;
        java.time.LocalDate newDate = date.minusDays(remainder);
        return newDate.getYear() * 10000L + newDate.getMonthValue() * 100L + newDate.getDayOfMonth();
    }catch(java.time.DateTimeException e){
        return timeBucket;
    }
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        return 0;
    }
    final int strLen = str.length();
    if (index < 0 || len < 0 || index + len > strLen) {
        throw new IllegalArgumentException("Invalid index or length");
    }
    int byteCount = 0;
    int i = index;
    final int end = index + len;
    while (i < end) {
        int codePoint = Character.codePointAt(str, i);
        if (codePoint <= 0x7F) {
            byteCount += 1;
        } else if (codePoint <= 0x7FF) {
            byteCount += 2;
        } else if (codePoint <= 0xFFFF) {
            byteCount += 3;
        } else {
            byteCount += 4;
        }
        i += Character.charCount(codePoint);
    }
    return byteCount;
}

