public void removeFromTreeEdgeList() {
    // Remove this edge from the first doubly linked list
    if (prev != null) {
        prev.next = next;
    }
    if (next != null) {
        next.prev = prev;
    }
    // Remove this edge from the second doubly linked list
    if (prevSibling != null) {
        prevSibling.nextSibling = nextSibling;
    }
    if (nextSibling != null) {
        nextSibling.prevSibling = prevSibling;
    }
    // Nullify this edge's own pointers to help GC
    prev = next = null;
    prevSibling = nextSibling = null;
}

public static String findAndSubst(String key, Properties props) {
    if (key == null || props == null) {
        return null;
    }
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    try {
        Pattern pattern = Pattern.compile("\\$\\{([^}]+)\\}");
        Matcher matcher = pattern.matcher(value);
        StringBuffer sb = new StringBuffer();
        while (matcher.find()) {
            String varName = matcher.group(1);
            String replacement = props.getProperty(varName);
            if (replacement == null) {
                replacement = "";
            }
            // Escape backslashes and dollar signs in the replacement string
            replacement = Matcher.quoteReplacement(replacement);
            matcher.appendReplacement(sb, replacement);
        }
        matcher.appendTail(sb);
        return sb.toString();
    } catch (Exception e) {
        // In case of any unexpected error, return the original value
        return value;
    }
}

