private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    if (str == null) {
        return suffix == null;
    }
    if (suffix == null) {
        return false;
    }
    int strLen = str.length();
    int suffLen = suffix.length();
    if (suffLen > strLen) {
        return false;
    }
    if (ignoreCase) {
        return str.regionMatches(true, strLen - suffLen, suffix, 0, suffLen);
    } else {
        return str.endsWith(suffix);
    }
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u == null) {
        return segments;
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    // Ignore leading '/' for absolute paths
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    if (path.isEmpty()) {
        return segments;
    }
    String[] parts = path.split("/");
    for (String part : parts) {
        String decoded = part;
        if (decode) {
            try {
                decoded = java.net.URLDecoder.decode(part, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (java.io.UnsupportedEncodingException e) {
                throw new RuntimeException(e);
            }
        }
        segments.add(new PathSegmentImpl(part, decoded));
    }
    return segments;
}

