private void pop(final String descriptor) {
    int count = 0;
    int i = 0;
    if (descriptor.startsWith("(")) {
        i++; // skip '('
        while (i < descriptor.length() && descriptor.charAt(i) != ')') {
            char c = descriptor.charAt(i);
            if (c == '[') {
                // skip array brackets
                while (i < descriptor.length() && descriptor.charAt(i) == '[') {
                    i++;
                }
                if (i < descriptor.length()) {
                    c = descriptor.charAt(i);
                }
            }
            if (c == 'L') {
                // object type
                i++; // skip 'L'
                while (i < descriptor.length() && descriptor.charAt(i) != ';') {
                    i++;
                }
                i++; // skip ';'
                count++;
            } else if (c == 'J' || c == 'D') {
                // long or double
                i++;
                count++;
            } else if (c == 'B' || c == 'C' || c == 'F' || c == 'I' || c == 'S' || c == 'Z') {
                i++;
                count++;
            } else {
                // unknown character, skip
                i++;
            }
        }
    } else {
        // non-method descriptor
        while (i < descriptor.length()) {
            char c = descriptor.charAt(i);
            if (c == '[') {
                while (i < descriptor.length() && descriptor.charAt(i) == '[') {
                    i++;
                }
                if (i < descriptor.length()) {
                    c = descriptor.charAt(i);
                }
            }
            if (c == 'L') {
                i++; // skip 'L'
                while (i < descriptor.length() && descriptor.charAt(i) != ';') {
                    i++;
                }
                i++; // skip ';'
                count++;
            } else if (c == 'J' || c == 'D') {
                i++;
                count++;
            } else if (c == 'B' || c == 'C' || c == 'F' || c == 'I' || c == 'S' || c == 'Z') {
                i++;
                count++;
            } else {
                i++;
            }
        }
    }
    if (pos < count) {
        throw new IllegalStateException("Stack underflow while popping descriptor: " + descriptor);
    }
    // Optionally clear popped slots
    for (int j = 0; j < count; j++) {
        stack[--pos] = null;
    }
}

