public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (out == null) {
        throw new NullPointerException("DataOutput is null");
    }
    if (node == null) {
        return 0;
    }
    int total = 0;
    LinkedBuffer current = node;
    while (current != null) {
        byte[] buf = current.buf;
        int start = current.start;
        int end = current.end;
        int len = end - start;
        if (len > 0) {
            out.write(buf, start, len);
            total += len;
        }
        current = current.next;
    }
    return total;
}

