@Override protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type == null) {
        throw new IllegalArgumentException("Target type cannot be null");
    }
    if (!Character.class.isAssignableFrom(type)) {
        throw new IllegalArgumentException("Target type must be Character");
    }
    if (value == null) {
        return null;
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return str.charAt(0);
        } else {
            throw new Exception("Cannot convert string to character: length not 1");
        }
    }
    if (value instanceof Number) {
        return (char) ((Number) value).intValue();
    }
    throw new Exception("Unsupported conversion from " + value.getClass().getName() + " to Character");
}

