public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate++;
    }
    int limit = Integer.MAX_VALUE;
    if (desiredCapacity >= 1000) {
        long l = (long) desiredCapacity * 111 / 100;
        limit = l > Integer.MAX_VALUE ? Integer.MAX_VALUE : (int) l;
    }
    while (candidate <= limit) {
        if (candidate == 3) {
            return 3;
        }
        if (candidate % 2 != 0 && candidate % 3 != 0) {
            boolean prime = true;
            for (int i = 5; i * i <= candidate; i += 6) {
                if (candidate % i == 0 || candidate % (i + 2) == 0) {
                    prime = false;
                    break;
                }
            }
            if (prime) {
                return candidate;
            }
        }
        candidate += 2;
    }
    while (candidate > 0) {
        if (candidate == 3) {
            return 3;
        }
        if (candidate % 2 != 0 && candidate % 3 != 0) {
            boolean prime = true;
            for (int i = 5; i * i <= candidate; i += 6) {
                if (candidate % i == 0 || candidate % (i + 2) == 0) {
                    prime = false;
                    break;
                }
            }
            if (prime) {
                return candidate;
            }
        }
        if (candidate > Integer.MAX_VALUE - 2) {
            break;
        }
        candidate += 2;
    }
    return Integer.MAX_VALUE;
}

