public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\' && i + 1 < len) {
            char next = str.charAt(i + 1);
            switch (next) {
                case 'b':
                    sb.append('\b');
                    i += 1;
                    break;
                case 't':
                    sb.append('\t');
                    i += 1;
                    break;
                case 'n':
                    sb.append('\n');
                    i += 1;
                    break;
                case 'f':
                    sb.append('\f');
                    i += 1;
                    break;
                case 'r':
                    sb.append('\r');
                    i += 1;
                    break;
                case '\\':
                    sb.append('\\');
                    i += 1;
                    break;
                case '\'':
                    sb.append('\'');
                    i += 1;
                    break;
                case '\"':
                    sb.append('\"');
                    i += 1;
                    break;
                case 'u':
                    if (i + 5 >= len) {
                        throw new Exception("Invalid unicode escape sequence at position " + i);
                    }
                    String hex = str.substring(i + 2, i + 6);
                    try {
                        int code = Integer.parseInt(hex, 16);
                        sb.append((char) code);
                    } catch (NumberFormatException e) {
                        throw new Exception("Invalid unicode escape sequence: \\u" + hex, e);
                    }
                    i += 5;
                    break;
                default:
                    if (next >= '0' && next <= '7') {
                        int j = i + 1;
                        int end = j;
                        while (end < len && end - j < 3 && str.charAt(end) >= '0' && str.charAt(end) <= '7') {
                            end++;
                        }
                        String oct = str.substring(j, end);
                        int value = Integer.parseInt(oct, 8);
                        sb.append((char) value);
                        i = end - 1;
                    } else {
                        sb.append(next);
                        i += 1;
                    }
                    break;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

