protected int removeUnusedNodes() {
    int removedCount = 0;
    try {
        if (root == null) {
            return 0;
        }
        // If the root itself is inactive, remove it entirely
        if (!root.isActive()) {
            root = null;
            return 1;
        }
        java.util.Deque<Category> stack = new java.util.ArrayDeque<>();
        stack.push(root);
        while (!stack.isEmpty()) {
            Category current = stack.pop();
            java.util.List<Category> children = current.getChildren();
            if (children == null) {
                continue;
            }
            // Iterate in reverse to safely remove elements while iterating
            for (int i = children.size() - 1; i >= 0; i--) {
                Category child = children.get(i);
                if (!child.isActive()) {
                    children.remove(i);
                    removedCount++;
                } else {
                    stack.push(child);
                }
            }
        }
    } catch (Exception e) {
        System.err.println("Error removing unused nodes: " + e.getMessage());
    }
    return removedCount;
}

