final String readUtf(final int constantPoolEntryIndex,final char[] charBuffer){
    // Validate input
    if (classFileBuffer == null) {
        throw new IllegalStateException("classFileBuffer is not initialized");
    }
    if (constantPoolEntryIndex <= 0) {
        throw new IllegalArgumentException("constantPoolEntryIndex must be > 0");
    }
    // Find the offset of the CONSTANT_Utf8 entry in the class file buffer
    int offset = getConstantPoolEntryOffset(constantPoolEntryIndex);
    if (offset < 0 || offset + 3 > classFileBuffer.length) {
        throw new IllegalArgumentException("Invalid constant pool entry index or corrupted class file");
    }
    // The first byte of the entry is the tag (should be 1 for CONSTANT_Utf8)
    if (classFileBuffer[offset] != 1) {
        throw new IllegalArgumentException("Entry at index " + constantPoolEntryIndex + " is not a CONSTANT_Utf8");
    }
    // Read the length of the UTF-8 string (2 bytes, big-endian)
    int length = ((classFileBuffer[offset + 1] & 0xFF) << 8) | (classFileBuffer[offset + 2] & 0xFF);
    if (length < 0 || offset + 3 + length > classFileBuffer.length) {
        throw new IllegalArgumentException("Invalid UTF-8 length for entry at index " + constantPoolEntryIndex);
    }
    if (length > charBuffer.length) {
        throw new IllegalArgumentException("Provided charBuffer is too small for the UTF-8 string");
    }
    // Decode the UTF-8 bytes into a String
    String utf8String = new String(classFileBuffer, offset + 3, length, java.nio.charset.StandardCharsets.UTF_8);
    // Copy the characters into the supplied buffer
    utf8String.getChars(0, utf8String.length(), charBuffer, 0);
    return utf8String;
}

