private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new NullPointerException("predicate must not be null");
    }
    if (start == null) {
        throw new NullPointerException("start must not be null");
    }
    if (stop == null) {
        throw new NullPointerException("stop must not be null");
    }
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    // If the starting node is the stop node, return immediately
    if (circ.node().equals(stop)) {
        return circ;
    }
    // Traverse the outer face until the stop node is reached or the predicate is satisfied
    while (!circ.node().equals(stop)) {
        if (predicate.test(circ.node())) {
            break;
        }
        circ.next();
    }
    return circ;
}

