public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength){
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non-negative");
    }
    if (byteLength == 0) {
        return this;
    }
    if (byteArrayValue == null) {
        // Put null bytes (zeros)
        if (this.length + byteLength > this.data.length) {
            this.enlarge(byteLength);
        }
        for (int i = 0; i < byteLength; i++) {
            this.data[this.length++] = 0;
        }
        return this;
    }
    if (byteOffset < 0 || byteOffset > byteArrayValue.length - byteLength) {
        throw new IllegalArgumentException("byteOffset out of bounds");
    }
    if (this.length + byteLength > this.data.length) {
        this.enlarge(byteLength);
    }
    System.arraycopy(byteArrayValue, byteOffset, this.data, this.length, byteLength);
    this.length += byteLength;
    return this;
}

