private void check(String modelName) throws IllegalStateException {
    if (modelName == null || modelName.isEmpty()) {
        throw new IllegalStateException("Model name cannot be null or empty");
    }
    try {
        java.util.List<Integer> indices = getShardingKeyIndices(modelName);
        if (indices == null || indices.isEmpty()) {
            throw new IllegalStateException("No sharding key indices found for model: " + modelName);
        }
        java.util.Collections.sort(indices);
        int expected = 0;
        for (int idx : indices) {
            if (idx != expected) {
                throw new IllegalStateException("Sharding key indices are not continuous for model: " + modelName);
            }
            expected++;
        }
    } catch (Exception e) {
