protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    try{
        if(tour==null || graph==null) return null;
        if(tour.isEmpty()) return null;
        // Build adjacency map
        Map<V, List<E>> adjacency = new HashMap<>();
        for(E e : tour){
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            adjacency.computeIfAbsent(src, k->new ArrayList<>()).add(e);
            adjacency.computeIfAbsent(tgt, k->new ArrayList<>()).add(e);
        }
        // Find start vertex (degree 1 if path, else any)
        V start = null;
        for(Map.Entry<V, List<E>> entry : adjacency.entrySet()){
            if(entry.getValue().size()==1){
                start = entry.getKey();
                break;
            }
        }
        if(start==null){
            // No vertex of degree 1, pick any
            start = adjacency.keySet().iterator().next();
        }
        List<E> orderedEdges = new ArrayList<>();
        Set<E> visited = new HashSet<>();
        V current = start;
        V prev = null;
        while(visited.size() < tour.size()){
            List<E> edges = adjacency.get(current);
            if(edges==null) break;
            boolean found = false;
            for(E e : edges){
                if(visited.contains(e)) continue;
                // Ensure we follow direction if graph is directed
                V src = graph.getEdgeSource(e);
                V tgt = graph.getEdgeTarget(e);
                if(prev!=null && !src.equals(prev) && !tgt.equals(prev)) continue;
                // Choose this edge
                orderedEdges.add(e);
                visited.add(e);
                prev = current;
                current = src.equals(current) ? tgt : src;
                found = true;
                break;
            }
            if(!found) break;
        }
        if(visited.size()!=tour.size()){
            // The edges do not form a single path
            return null;
        }
        double weight = 0.0;
        for(E e : orderedEdges){
            weight += graph.getEdgeWeight(e);
        }
        V end = current;
        return new GraphWalk<>(graph, start, end, orderedEdges, weight);
    }catch(Exception e){
        return null;
    }
}

