                        break;
                    case '\\':
                        sb.append('\\');
                        i++;
                        break;
                    case '\'':
                        sb.append('\'');
                        i++;
                        break;
                    case '\"':
                        sb.append('\"');
                        i++;
                        break;
                    default:
                        sb.append(next);
                        i++;
                        break;
                }
            } else {
                sb.append(c);
            }
        }
        return sb.toString();
    } catch (Exception e) {
        // In case of any unexpected error, return the original input
        return input;
    }
}

