private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }
    try {
        // Detach from previous node
        if (node.prev != null) {
            node.prev.next = node.next;
        } else {
            // node is the first element
            first = node.next;
        }

        // Detach from next node
        if (node.next != null) {
            node.next.prev = node.prev;
        } else {
            // node is the last element
            last = node.prev;
        }

        // Clear the node's own links
        node.prev = null;
        node.next = null;

        // Update size
        if (size > 0) {
            size--;
        }

        return true;
    } catch (Exception e) {
        // In case of any unexpected error, return false
        return false;
    }
}

