private String parseToken(final char[] terminators){
    try {
        // If no terminators provided, consume until end of input
        if (terminators == null || terminators.length == 0) {
            i1 = pos;
            i2 = pos;
            while (hasChar()) {
                i2++;
                pos++;
            }
            return getToken(false);
        }
        // Start of token
        i1 = pos;
        i2 = pos;
        while (hasChar()) {
            char current = chars[pos];
            if (isOneOf(current, terminators)) {
                break;
            }
            i2++;
            pos++;
        }
        return getToken(false);
