private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null || bounds.isEmpty()){
        return new Pair<>(new ArrayList<>(), 0L);
    }
    int size = bounds.size();
    List<Integer> suffix = new ArrayList<>(size);
    for (int i = 0; i < size; i++) {
        suffix.add(0);
    }
    long running = 0;
    for (int i = size - 1; i >= 0; i--) {
        Integer val = bounds.get(i);
        if (val == null) {
            throw new IllegalArgumentException("bounds contains null at index " + i);
        }
        running += val;
        suffix.set(i, (int) running);
    }
    return new Pair<>(suffix, running);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new IllegalArgumentException("Array cannot be null");
    }
    if (from < 0 || to >= arr.length) {
        throw new IllegalArgumentException("Index out of bounds");
    }
    if (from > to) {
        return;
    }
    int i = from;
    int j = to;
    while (i < j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null || list == this) {
        return;
    }
    // Start with the first node of the source list
    ListNodeImpl<E> node = list.getFirstNode();
    while (node != null) {
        // Keep a reference to the next node before we modify the current one
        ListNodeImpl<E> next = node.getNext();
        try {
            // Remove the node from the source list
            list.removeListNode(node);
            // Add the node to this list
            this.addListNode(node);
        } catch (Exception e) {
            // If an exception occurs, rethrow as a runtime exception to avoid silent failures
            throw new RuntimeException("Failed to move node during moveAllListNodes", e);
        }
        // Move to the next node in the original list
        node = next;
    }
}

