private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        return false;
    }
    // A graph with 0 or 1 vertex is trivially a clique
    if (vertices.size() <= 1) {
        return true;
    }
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (!v1.equals(v2)) {
                // If the graph does not contain an edge between v1 and v2, it's not a clique
                if (graph.getEdge(v1, v2) == null) {
                    return false;
                }
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys){
    if (keys == null) {
        throw new IllegalArgumentException("keys list cannot be null");
    }
    List<Integer> lowerBounds = new ArrayList<>(keys.size());
    for (K keyObj : keys) {
        if (keyObj == null) {
            lowerBounds.add(null);
            continue;
        }
        Integer key;
        try {
            key = (Integer) keyObj;
        } catch (ClassCastException e) {
            throw new IllegalArgumentException("key is not an Integer", e);
        }
        Integer maxLower = null;
        for (K otherObj : keys) {
            if (otherObj == null) continue;
            Integer other;
            try {
                other = (Integer) otherObj;
            } catch (ClassCastException e) {
                throw new IllegalArgumentException("key is not an Integer", e);
            }
            if (other < key && (maxLower == null || other > maxLower)) {
                maxLower = other;
            }
        }
        lowerBounds.add(maxLower);
    }
    return lowerBounds;
}

private void pop(final String descriptor) {
    int count = 0;
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }
    if (descriptor.charAt(0) == '(') {
        int i = 1;
        while (i < descriptor.length() && descriptor.charAt(i) != ')') {
            char c = descriptor.charAt(i);
            if (c == '[') {
                // array type: skip all '['
                while (i < descriptor.length() && descriptor.charAt(i) == '[') {
                    i++;
                }
                // object type inside array
                if (i < descriptor.length() && descriptor.charAt(i) == 'L') {
                    i = descriptor.indexOf(';', i) + 1;
                } else {
                    // primitive array
                    i++;
                }
            } else if (c == 'L') {
                // object type
                i = descriptor.indexOf(';', i) + 1;
            } else {
                // primitive type
                i++;
            }
            count++;
        }
    } else {
        // single type descriptor
        count = 1;
    }
    for (int j = 0; j < count; j++) {
        if (pos <= 0) {
            throw new IllegalStateException("Stack underflow");
        }
        pos--;
    }
}

