    for (K key : keys) {
        if (key == null) {
            bounds.add(0);
            continue;
        }
        try {
            if (key instanceof Integer) {
                bounds.add((Integer) key);
            } else if (key instanceof Number) {
                bounds.add(((Number) key).intValue());
            } else {
                bounds.add(key.hashCode());
            }
        } catch (Exception e) {
            bounds.add(0);
        }
    }
    return bounds;
}

