public static String applyRelativePath(String path, String relativePath) {
    if (path == null) {
        return relativePath;
    }
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }

    boolean isAbsolute = path.startsWith("/");
    String[] pathParts = path.split("/");
    String[] relParts = relativePath.split("/");

    java.util.List<String> stack = new java.util.ArrayList<>();

    // Process base path components
    for (String part : pathParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            } else if (!isAbsolute) {
                stack.add("..");
            }
        } else {
            stack.add(part);
        }
    }

    // Process relative path components
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            } else if (!isAbsolute) {
                stack.add("..");
            }
        } else {
            stack.add(part);
        }
    }

    // Build the resulting path
    StringBuilder result = new StringBuilder();
    if (isAbsolute) {
        result.append("/");
    }
    for (int i = 0; i < stack.size(); i++) {
        if (i > 0) {
            result.append("/");
        }
        result.append(stack.get(i));
    }

    // If result is empty, return "." to represent current directory
    if (result.length() == 0) {
        return ".";
    }
    return result.toString();
}

