        }
    } catch (Exception e) {
        // If the node does not support virtual checks, ignore and use as is
    }
    if (this._edges == null) {
        return null;
    }
    for (Edge e : this._edges) {
        if ((e.getFrom() == prev && e.getTo() == next) ||
            (e.getFrom() == next && e.getTo() == prev)) {
            return e;
        }
    }
    return null;
}

public static boolean substringMatch(CharSequence str,int index,CharSequence substring){
    if(str == null || substring == null){
        return false;
    }
    int strLen = str.length();
    int subLen = substring.length();
    if(index < 0 || index > strLen){
        return false;
    }
    if(index + subLen > strLen){
        return false;
    }
    for(int i = 0; i < subLen; i++){
        if(str.charAt(index + i) != substring.charAt(i)){
            return false;
        }
    }
    return true;
}

