private String buildContentRange() {
    try {
        // Validate range values
        if (contentRangeStart < 0 || contentRangeEnd < 0 || contentRangeStart > contentRangeEnd) {
            return null;
        }
        // Determine total length representation
        String total = (contentLength > 0) ? Long.toString(contentLength) : "*";
        // Construct the Content-Range header value
        return "bytes " + contentRangeStart + "-" + contentRangeEnd + "/" + total;
    } catch (Exception e) {
        // In case of any unexpected error, return null
        return null;
    }
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new IllegalArgumentException("file must not be null");
    }
    if (!file.exists() || !file.isFile()) {
        throw new java.io.FileNotFoundException("File not found: " + file);
    }
    if (timeRanges == null) {
        throw new IllegalArgumentException("timeRanges must not be null");
    }
    java.util.List<ThreadSnapshot> snapshots = new java.util.ArrayList<>();
    try (java.io.BufferedReader reader = new java.io.BufferedReader(new java.io.FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }
            ThreadSnapshot snapshot;
            try {
                snapshot = ThreadSnapshot.parse(line);
            } catch (Exception e) {
                // Skip malformed line
                continue;
            }
            if (snapshot == null) {
                continue;
            }
            long ts = snapshot.getTimestamp();
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (range == null) {
                    continue;
                }
                if (range.contains(ts)) {
                    snapshots.add(snapshot);
                    break;
                }
            }
        }
    }
    return snapshots;
}
